// Thao tác tính toán giá trị đơn hàng E-commerce đơn giản
function calculateCartTotal() {
  return 150000 + 30000; // Tổng tiền hàng + Phí vận chuyển
}

calculateCartTotal();

// Minh họa luồng thực thi Call Stack trong V8 Engine
function checkInventory() {
  return true;
}

function processPayment() {
  checkInventory(); // checkInventory được đẩy vào đỉnh Call Stack
}

processPayment(); // processPayment được đẩy vào Call Stack đầu tiên

progressive_examples.raw_code:
// Tệp script.js - Mô phỏng xử lý luồng thực thi đơn hàng E-commerce

// Hàm kiểm tra thông tin kho hàng
function validateStock() {
    // [NOTE] Hàm này thực thi và kết thúc cuối cùng trong chuỗi lời gọi
    return "Hàng còn trong kho";
}

// Hàm tạo mã hóa đơn
function generateInvoice() {
    validateStock(); // V8 đẩy validateStock() vào đỉnh Call Stack
}

// Hàm khởi tạo đơn hàng E-commerce
function createOrder() {
    generateInvoice(); // V8 đẩy generateInvoice() vào Call Stack
}

// Điểm bắt đầu thực thi chương trình
createOrder();

// Tệp script.js - Nâng cấp tính toán đơn hàng và phân bổ bộ nhớ V8

// Hàm tính tiền sản phẩm
function calculateSubtotal() {
    return 500000; // Giá trị đơn hàng cố định
}

// Hàm tính tiền chiết khấu E-commerce
function calculateDiscount() {
    return 50000; // Tiền giảm giá VIP
}

// Hàm tổng hợp hóa đơn thanh toán
function processFinalCheckout() {
    // V8 cấp phát bộ nhớ cho các phép toán và đẩy hàm vào Call Stack
    function getFinalAmount() {
        return calculateSubtotal() - calculateDiscount();
    }

    return getFinalAmount();
}

// Thực thi quy trình thanh toán đơn hàng
processFinalCheckout();

// Tệp script.js - Xử lý tính toán giảm giá bậc thang an toàn

// Hàm tính giảm giá cho đơn hàng doanh nghiệp với điều kiện dừng an toàn
function applyTieredDiscount(totalAmount, tierLevel) {
    // [NOTE] Điều kiện dừng để ngăn chặn lỗi nổ Call Stack (Stack Overflow)
    if (tierLevel <= 0) {
        return totalAmount;
    }

    // Giảm 5% cho mỗi cấp độ VIP
    function calculateDiscountedValue() {
        return totalAmount * 0.95;
    }

    // Lời gọi đệ quy tiến về điểm dừng
    return applyTieredDiscount(calculateDiscountedValue(), tierLevel - 1);
}

// Thực thi áp dụng 3 cấp độ giảm giá cho đơn hàng 1,000,000 VND
applyTieredDiscount(1000000, 3);

