// LỖI: Hàm gọi đệ quy liên tục không có điều kiện dừng
function processOrderLoop() {
    processOrderLoop(); // Gây lỗi Maximum call stack size exceeded
}
processOrderLoop();

gotchas_and_errors.code_good:
// CHUẨN: Bổ sung điều kiện dừng (Base case) cho luồng thực thi
function processOrderLoop(count) {
    if (count <= 0) {
        return "Hoàn tất xử lý đơn hàng";
    }
    return processOrderLoop(count - 1);
}
processOrderLoop(5);

